#include <bits/stdc++.h>
using namespace std;
using int64 = long long;

int64 cube(int64 x) {
    return x * x * x;
}

int64 foo(int64 n) {
    int64 ans = 0;
    for (int64 k = 2; ; ++k) {
        int64 c = cube(k);
        if (c > n) break;
        int64 x = n / c;
        if (x == 0) break;
        ans += x;
    }
    return ans;
}

int64 bin_search(function<bool(int64)> f, int64 lo, int64 hi) {
    hi++;
    while (lo < hi) {
        int64 mid = lo + (hi - lo) / 2;
        if (f(mid)) {
            hi = mid;
        } else {
            lo = mid + 1;
        }
    }
    return lo;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int64 m;
    if (!(cin >> m)) return 0;

    const int64 mx = 4949100894494448LL;

    auto check = [&](int64 n) -> bool {
        return foo(n) >= m;
    };

    int64 p = bin_search(check, 1, mx);

    if (foo(p) != m) {
        p = -1;
    }

    cout << p << "\n";

    return 0;
}

